package com.efficientbrutus;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum BannerStyle
{
	LARGE("Large banner"),
	COMPACT("Compact"),
	OVERHEAD("Above player");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.efficientbrutus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

class BrutusStatsOverlay extends OverlayPanel
{
	private final EfficientBrutusPlugin plugin;
	private final EfficientBrutusConfig config;

	@Inject
	BrutusStatsOverlay(EfficientBrutusPlugin plugin, EfficientBrutusConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Reset session", "Brutus stats", e -> plugin.resetSession());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showStats() || !plugin.isInPen())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Brutus")
			.color(Color.ORANGE)
			.build());

		int allTime = plugin.getAllTimeKills();
		addLine("All time:", allTime < 0 ? "?" : QuantityFormatter.formatNumber(allTime));
		if (plugin.getHardModeKills() > 0)
		{
			addLine("  Hard mode:", QuantityFormatter.formatNumber(plugin.getHardModeKills()));
		}

		int kills = plugin.getSessionKills();
		Duration elapsed = plugin.getSessionDuration();
		addLine("Session:", String.valueOf(kills));
		addLine("Kills/hr:", kills == 0 ? "-" : String.format("%.1f", plugin.getKillsPerHour()));
		addLine("Avg kill:", kills == 0 ? "-" : formatDuration(elapsed.dividedBy(kills)));
		addLine("Time:", formatDuration(elapsed));

		return super.render(graphics);
	}

	private void addLine(String left, String right)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.build());
	}

	private static String formatDuration(Duration d)
	{
		long s = d.getSeconds();
		if (s >= 3600)
		{
			return String.format("%d:%02d:%02d", s / 3600, (s % 3600) / 60, s % 60);
		}
		return String.format("%d:%02d", s / 60, s % 60);
	}
}

package com.efficientbrutus;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

class CowbellItemOverlay extends WidgetItemOverlay
{
	private final EfficientBrutusPlugin plugin;
	private final EfficientBrutusConfig config;
	private final ItemManager itemManager;

	@Inject
	CowbellItemOverlay(EfficientBrutusPlugin plugin, EfficientBrutusConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInventory();
		showOnEquipment();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!plugin.isRingReminderActive() || !config.highlightAmulet()
			|| !EfficientBrutusPlugin.COWBELL_IDS.contains(itemId))
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), Color.YELLOW);
		graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
	}
}

package com.efficientbrutus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Ring-the-cowbell reminder, drawn in one of several styles, with an optional flashing red
 * border around the game view.
 */
class CowbellReminderOverlay extends Overlay
{
	private static final String TITLE = "RING THE COWBELL!";
	private static final Color DARK = new Color(20, 20, 20, 220);
	private static final Color BORDER_RED = new Color(255, 0, 0, 140);
	private static final int BORDER_WIDTH = 10;

	private static final Font LARGE_TITLE = FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 36f);
	private static final Font LARGE_SUB = FontManager.getRunescapeBoldFont().deriveFont(20f);
	private static final Font COMPACT_FONT = FontManager.getRunescapeBoldFont().deriveFont(20f);
	private static final Font OVERHEAD_FONT = FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 28f);

	private final EfficientBrutusPlugin plugin;
	private final EfficientBrutusConfig config;
	private final Client client;

	@Inject
	CowbellReminderOverlay(EfficientBrutusPlugin plugin, EfficientBrutusConfig config, Client client)
	{
		this.plugin = plugin;
		this.config = config;
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.isRingReminderActive())
		{
			return null;
		}

		// "on" is the highlighted half of the flash cycle; always on when flashing is disabled
		boolean on = !config.flashBanner() || (client.getGameCycle() / 20) % 2 == 0;
		Color main = config.bannerColor();
		String countdown = String.format("%.1fs left", plugin.getRingSecondsLeft());

		if (config.screenBorder() && on)
		{
			drawScreenBorder(g);
		}

		switch (config.bannerStyle())
		{
			case LARGE:
				drawLarge(g, on, main, countdown);
				break;
			case COMPACT:
				drawCompact(g, on, main, countdown);
				break;
			case OVERHEAD:
				drawOverhead(g, on, main, countdown);
				break;
		}

		return null;
	}

	private void drawScreenBorder(Graphics2D g)
	{
		Stroke old = g.getStroke();
		g.setStroke(new BasicStroke(BORDER_WIDTH));
		g.setColor(BORDER_RED);
		g.drawRect(client.getViewportXOffset() + BORDER_WIDTH / 2, client.getViewportYOffset() + BORDER_WIDTH / 2,
			client.getViewportWidth() - BORDER_WIDTH, client.getViewportHeight() - BORDER_WIDTH);
		g.setStroke(old);
	}

	/** Big two-line box, a quarter of the way down the game view. */
	private void drawLarge(Graphics2D g, boolean on, Color main, String countdown)
	{
		final int pad = 14;
		g.setFont(LARGE_TITLE);
		FontMetrics tfm = g.getFontMetrics();
		g.setFont(LARGE_SUB);
		FontMetrics sfm = g.getFontMetrics();

		int titleW = tfm.stringWidth(TITLE);
		int subW = sfm.stringWidth(countdown);
		int boxW = Math.max(titleW, subW) + pad * 2;
		int boxH = tfm.getHeight() + sfm.getHeight() + pad * 2;
		int centerX = client.getViewportXOffset() + client.getViewportWidth() / 2;
		int boxX = centerX - boxW / 2;
		int boxY = client.getViewportYOffset() + client.getViewportHeight() / 4 - boxH / 2;

		drawBox(g, boxX, boxY, boxW, boxH, on, main, 3);

		int titleY = boxY + pad + tfm.getAscent();
		g.setFont(LARGE_TITLE);
		drawShadowed(g, TITLE, centerX - titleW / 2, titleY, on ? Color.WHITE : Color.YELLOW);
		g.setFont(LARGE_SUB);
		drawShadowed(g, countdown, centerX - subW / 2, titleY + tfm.getDescent() + sfm.getAscent(), Color.WHITE);
	}

	/** Single-line box near the top of the game view. */
	private void drawCompact(Graphics2D g, boolean on, Color main, String countdown)
	{
		final int pad = 8;
		String text = TITLE + "  " + countdown;
		g.setFont(COMPACT_FONT);
		FontMetrics fm = g.getFontMetrics();

		int textW = fm.stringWidth(text);
		int boxW = textW + pad * 2;
		int boxH = fm.getHeight() + pad * 2;
		int centerX = client.getViewportXOffset() + client.getViewportWidth() / 2;
		int boxX = centerX - boxW / 2;
		int boxY = client.getViewportYOffset() + 40;

		drawBox(g, boxX, boxY, boxW, boxH, on, main, 2);
		drawShadowed(g, text, centerX - textW / 2, boxY + pad + fm.getAscent(), on ? Color.WHITE : Color.YELLOW);
	}

	/** Large text floating above the local player, no box. */
	private void drawOverhead(Graphics2D g, boolean on, Color main, String countdown)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		g.setFont(OVERHEAD_FONT);
		Point loc = player.getCanvasTextLocation(g, TITLE, player.getLogicalHeight() + 80);
		if (loc == null)
		{
			return;
		}

		FontMetrics fm = g.getFontMetrics();
		int centerX = loc.getX() + fm.stringWidth(TITLE) / 2;
		// Solid colour for the text itself so it stays readable over the scene
		Color textColor = on ? new Color(main.getRed(), main.getGreen(), main.getBlue()) : Color.YELLOW;
		drawShadowed(g, TITLE, loc.getX(), loc.getY(), textColor);

		g.setFont(LARGE_SUB);
		int subW = g.getFontMetrics().stringWidth(countdown);
		drawShadowed(g, countdown, centerX - subW / 2, loc.getY() + g.getFontMetrics().getHeight(), Color.WHITE);
	}

	private static void drawBox(Graphics2D g, int x, int y, int w, int h, boolean on, Color main, int outline)
	{
		g.setColor(on ? main : DARK);
		g.fillRect(x, y, w, h);
		g.setColor(on ? Color.YELLOW : main);
		Stroke old = g.getStroke();
		g.setStroke(new BasicStroke(outline));
		g.drawRect(x, y, w, h);
		g.setStroke(old);
	}

	private static void drawShadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 2, y + 2);
		g.setColor(color);
		g.drawString(text, x, y);
	}
}

package com.efficientbrutus;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Units;

@ConfigGroup(EfficientBrutusConfig.GROUP)
public interface EfficientBrutusConfig extends Config
{
	String GROUP = "efficient-brutus";

	@ConfigItem(
		keyName = "showStats",
		name = "Show stats overlay",
		description = "Show all-time kills, session kills and kills per hour",
		position = 1
	)
	default boolean showStats()
	{
		return true;
	}

	@ConfigItem(
		keyName = "cowbellReminder",
		name = "Cowbell reminder",
		description = "After each kill, remind you to ring the cowbell amulet so Brutus respawns faster",
		position = 2
	)
	default boolean cowbellReminder()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bannerStyle",
		name = "Reminder style",
		description = "How the ring reminder is shown: a large banner, a compact box at the top, or text above your player",
		position = 10
	)
	default BannerStyle bannerStyle()
	{
		return BannerStyle.LARGE;
	}

	@ConfigItem(
		keyName = "flashBanner",
		name = "Flash reminder",
		description = "Make the ring reminder flash",
		position = 11
	)
	default boolean flashBanner()
	{
		return true;
	}

	@ConfigItem(
		keyName = "screenBorder",
		name = "Screen border",
		description = "Show a red border around the game view while the ring reminder is showing",
		position = 12
	)
	default boolean screenBorder()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "bannerColor",
		name = "Reminder colour",
		description = "Main colour of the ring reminder",
		position = 13
	)
	default Color bannerColor()
	{
		return new Color(200, 20, 20, 220);
	}

	@ConfigItem(
		keyName = "cowbellNotification",
		name = "Cowbell notification",
		description = "Also send a RuneLite notification when it's time to ring the cowbell amulet",
		position = 20
	)
	default Notification cowbellNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "highlightAmulet",
		name = "Highlight amulet",
		description = "Outline the cowbell amulet in your inventory/equipment while the reminder is showing",
		position = 21
	)
	default boolean highlightAmulet()
	{
		return true;
	}

	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "sessionTimeout",
		name = "Session timeout",
		description = "Reset session stats after this many minutes without a kill. 0 = never reset automatically",
		position = 30
	)
	default int sessionTimeout()
	{
		return 10;
	}
}

package com.efficientbrutus;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import java.util.Set;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Efficient Brutus",
	description = "Brutus kill stats and cowbell amulet ring reminders",
	tags = {"brutus", "cow", "boss", "kc", "cowbell"}
)
public class EfficientBrutusPlugin extends Plugin
{
	static final Set<Integer> BRUTUS_IDS = ImmutableSet.of(NpcID.COWBOSS, NpcID.COWBOSS_HARDMODE);
	static final Set<Integer> COWBELL_IDS = ImmutableSet.of(ItemID.COWBELL_AMULET, ItemID.COWBELL_AMULET_EMPTY);

	/**
	 * Brutus naturally respawns 36 ticks after death; ringing the cowbell makes him respawn
	 * 13 ticks after ringing. Ringing later than ~tick 23 makes the respawn slower than natural,
	 * so the reminder only shows during the window where ringing still helps.
	 */
	private static final int RING_WINDOW_TICKS = 20;
	/** Ignore duplicate death signals (death event, despawn, kc varp) for the same kill. */
	private static final int DEATH_DEDUPE_TICKS = 15;
	/** Ringing in the first few ticks after death does nothing, so delay the reminder. */
	private static final int RING_DELAY_TICKS = 5;
	private static final int NO_DEATH = Integer.MIN_VALUE / 2;

	@Inject
	private Client client;

	@Inject
	private EfficientBrutusConfig config;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BrutusStatsOverlay statsOverlay;

	@Inject
	private CowbellReminderOverlay reminderOverlay;

	@Inject
	private CowbellItemOverlay itemOverlay;

	private NPC brutus;

	/**
	 * True once Brutus has spawned in the current scene. The pen is an instance, so entering or
	 * leaving it always triggers a scene load, which clears this.
	 */
	@Getter
	private boolean inPen;

	// Kill count tracking (from the server-side kc varps)
	private boolean kcReady;
	private int normalKc = -1;
	private int hardKc = -1;

	// Session stats
	@Getter
	private int sessionKills;
	private Instant sessionStart;
	private Instant lastActivity;

	// Cowbell reminder
	@Getter
	private boolean ringReminderActive;
	/** Brutus died and the reminder will show once RING_DELAY_TICKS have passed. */
	private boolean ringReminderPending;
	private int lastDeathTick = NO_DEATH;

	@Override
	protected void startUp()
	{
		overlayManager.add(statsOverlay);
		overlayManager.add(reminderOverlay);
		overlayManager.add(itemOverlay);
		kcReady = false;
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(statsOverlay);
		overlayManager.remove(reminderOverlay);
		overlayManager.remove(itemOverlay);
		brutus = null;
		inPen = false;
		clearReminder();
		resetSession();
	}

	private void clearReminder()
	{
		ringReminderPending = false;
		ringReminderActive = false;
	}

	@Provides
	EfficientBrutusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EfficientBrutusConfig.class);
	}

	// ---------------------------------------------------------------- stats

	/** All-time kills (normal + hard mode), or -1 if not known yet. */
	int getAllTimeKills()
	{
		if (normalKc < 0)
		{
			return -1;
		}
		return normalKc + Math.max(hardKc, 0);
	}

	int getHardModeKills()
	{
		return hardKc;
	}

	Duration getSessionDuration()
	{
		return sessionStart == null ? Duration.ZERO : Duration.between(sessionStart, Instant.now());
	}

	double getKillsPerHour()
	{
		long seconds = getSessionDuration().getSeconds();
		if (sessionKills == 0 || seconds <= 0)
		{
			return 0;
		}
		return sessionKills * 3600.0 / seconds;
	}

	/** Seconds left in which ringing the cowbell still speeds up the respawn. */
	double getRingSecondsLeft()
	{
		int ticksLeft = RING_WINDOW_TICKS - (client.getTickCount() - lastDeathTick);
		return Math.max(ticksLeft, 0) * 0.6;
	}

	void resetSession()
	{
		sessionKills = 0;
		sessionStart = null;
		lastActivity = null;
	}

	private void touchSession()
	{
		Instant now = Instant.now();
		if (sessionStart == null)
		{
			sessionStart = now;
		}
		lastActivity = now;
	}

	// ---------------------------------------------------------------- events

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.LOGGING_IN)
		{
			kcReady = false;
			// The client tick counter isn't guaranteed to carry across logins
			lastDeathTick = NO_DEATH;
		}
		if (state == GameState.LOADING || state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Left the pen (or the scene changed): nothing to ring for any more
			brutus = null;
			inPen = false;
			clearReminder();
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!kcReady && client.getGameState() == GameState.LOGGED_IN)
		{
			// Varps are synced during login, so by the first tick these are the real totals.
			normalKc = client.getVarpValue(VarPlayerID.TOTAL_COWBOSS_KILLS);
			hardKc = client.getVarpValue(VarPlayerID.TOTAL_COWBOSS_HARDMODE_KILLS);
			kcReady = true;
			log.debug("Brutus kc baseline: normal={}, hard={}", normalKc, hardKc);
		}

		if (ringReminderPending && client.getTickCount() - lastDeathTick >= RING_DELAY_TICKS)
		{
			ringReminderPending = false;
			ringReminderActive = true;
			notifier.notify(config.cowbellNotification(), "Ring your cowbell amulet!");
		}

		if (ringReminderActive && client.getTickCount() - lastDeathTick > RING_WINDOW_TICKS)
		{
			// Too late now; ringing would delay the respawn.
			ringReminderActive = false;
		}

		int timeout = config.sessionTimeout();
		if (timeout > 0 && lastActivity != null && brutus == null
			&& Duration.between(lastActivity, Instant.now()).toMinutes() >= timeout)
		{
			log.debug("Brutus session timed out");
			resetSession();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!kcReady)
		{
			return;
		}

		int varp = event.getVarpId();
		if (varp == VarPlayerID.TOTAL_COWBOSS_KILLS)
		{
			normalKc = handleKcChange(normalKc, event.getValue());
		}
		else if (varp == VarPlayerID.TOTAL_COWBOSS_HARDMODE_KILLS)
		{
			hardKc = handleKcChange(hardKc, event.getValue());
		}
	}

	private int handleKcChange(int previous, int value)
	{
		int delta = value - previous;
		if (previous >= 0 && delta > 0 && delta <= 3)
		{
			sessionKills += delta;
			touchSession();
			onBrutusDeath();
			log.debug("Brutus kill detected, kc now {}", value);
		}
		return value;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		// Brutus also stands in the normal (non-instanced) cow field before being released;
		// only the instanced pen counts.
		if (BRUTUS_IDS.contains(npc.getId()) && client.getTopLevelWorldView().isInstance())
		{
			brutus = npc;
			inPen = true;
			clearReminder();
			touchSession();
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc == brutus)
		{
			if (npc.isDead())
			{
				onBrutusDeath();
			}
			brutus = null;
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		// Hard mode has a ghost phase, so only trust the kc varp for hard mode kills.
		if (actor instanceof NPC && actor == brutus && ((NPC) actor).getId() == NpcID.COWBOSS)
		{
			onBrutusDeath();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!ringReminderActive || !"Ring".equalsIgnoreCase(event.getMenuOption()))
		{
			return;
		}

		boolean isCowbell = COWBELL_IDS.contains(event.getItemId())
			|| Text.removeTags(event.getMenuTarget()).toLowerCase().contains("cowbell");
		if (isCowbell)
		{
			ringReminderActive = false;
		}
	}

	private void onBrutusDeath()
	{
		int tick = client.getTickCount();
		if (tick - lastDeathTick < DEATH_DEDUPE_TICKS)
		{
			return;
		}
		lastDeathTick = tick;

		if (!config.cowbellReminder() || !hasCowbell())
		{
			return;
		}

		ringReminderPending = true;
	}

	private boolean hasCowbell()
	{
		return containerHasCowbell(client.getItemContainer(InventoryID.INV))
			|| containerHasCowbell(client.getItemContainer(InventoryID.WORN));
	}

	private static boolean containerHasCowbell(ItemContainer container)
	{
		if (container == null)
		{
			return false;
		}
		for (int id : COWBELL_IDS)
		{
			if (container.contains(id))
			{
				return true;
			}
		}
		return false;
	}
}

